# 2d — PRUEBA QUE NO VIGILA: una funcion test_ que devuelve un valor con return y no
# tiene ningun assert. En pytest eso PASA SIEMPRE: el return se ignora y la prueba
# entra verde sin vigilar nada. Medido el 2026-09-21: una vigia asi entro verde sin
# que existiera su arreglo; se escanearon todas las demas del proyecto y era la unica.
# Un return sin valor no cuenta. Si el texto no se puede leer, no se dice nada.
try:
    _ruta_r = str(p.get("archivo") or "")
    if _ruta_r.lower().endswith(".py"):
        _texto_r = nuevo
        if es_un_pedazo(_texto_r):
            _texto_r = None
        if _texto_r:
            try:
                _arbol_r = ast.parse(_texto_r)
            except SyntaxError:
                try:
                    _arbol_r = ast.parse(textwrap.dedent(_texto_r))
                except SyntaxError:
                    _arbol_r = None
            except Exception:
                _arbol_r = None
            if _arbol_r is not None:
                for _nodo_r in ast.walk(_arbol_r):
                    if not isinstance(_nodo_r, (ast.FunctionDef, ast.AsyncFunctionDef)):
                        continue
                    if not _nodo_r.name.startswith("test_"):
                        continue
                    _tiene_assert_r = any(
                        isinstance(_h, ast.Assert) for _h in ast.walk(_nodo_r))
                    _return_con_valor_r = False
                    for _h in ast.walk(_nodo_r):
                        if isinstance(_h, ast.Return) and _h.value is not None:
                            _return_con_valor_r = True
                            break
                    if _return_con_valor_r and not _tiene_assert_r:
                        fallos.append(
                            "PRUEBA QUE NO VIGILA: la prueba '%s' devuelve un valor con "
                            "return y no tiene ningun assert. En pytest eso PASA SIEMPRE: "
                            "el return se ignora y la prueba entra verde sin vigilar nada. "
                            "Hay que usar assert." % _nodo_r.name)
except Exception:
    pass

