# mensaje que habla de que la pieza no existe todavia. Una prueba saltada NO PUEDE
# ponerse roja: mientras la pieza no exista tiene que fallar con assert, no saltarse.
# Si el texto no se puede leer, no se dice nada.
try:
    _ruta_s = str(p.get("archivo") or "")
    if _ruta_s.lower().endswith(".py"):
        _texto_s = nuevo
        if es_un_pedazo(_texto_s):
            _texto_s = None
        if _texto_s:
            try:
                _arbol_s = ast.parse(_texto_s)
            except SyntaxError:
                try:
                    _arbol_s = ast.parse(textwrap.dedent(_texto_s))
                except SyntaxError:
                    _arbol_s = None
            except Exception:
                _arbol_s = None
            if _arbol_s is not None:
                _palabras_s = ("no existe", "no existe todavia", "todavia no existe",
                               "aun no existe", "no esta", "no esta todavia",
                               "todavia no esta", "falta", "pendiente")
                for _nodo_s in ast.walk(_arbol_s):
                    if not isinstance(_nodo_s, (ast.FunctionDef, ast.AsyncFunctionDef)):
                        continue
                    if not _nodo_s.name.startswith("test_"):
                        continue
                    for _h in ast.walk(_nodo_s):
                        if not isinstance(_h, ast.Call):
                            continue
                        _es_skip_s = False
                        _fn_s = _h.func
                        if isinstance(_fn_s, ast.Attribute) and _fn_s.attr == "SkipTest":
                            _es_skip_s = True
                        if isinstance(_fn_s, ast.Attribute) and _fn_s.attr == "skip":
                            _es_skip_s = True
                        if isinstance(_fn_s, ast.Name) and _fn_s.id == "skip":
                            _es_skip_s = True
                        if not _es_skip_s:
                            continue
                        _msg_s = ""
                        if _h.args:
                            try:
                                _msg_s = str(ast.literal_eval(_h.args[0]))
                            except Exception:
                                _msg_s = ""
                        _msg_s = _msg_s.lower()
                        if any(_w in _msg_s for _w in _palabras_s):
                            fallos.append(
                                "PRUEBA SALTADA: la prueba '%s' se salta diciendo que la "
                                "pieza no existe todavia. Una prueba saltada NO PUEDE "
                                "ponerse roja: mientras la pieza no exista tiene que "
                                "fallar con assert." % _nodo_s.name)
                            break
except Exception:
    pass

